    """8.2: у существующих городов (seed_regions, ~300) - имя для поиска и признак «крупный»."""
    from local_listings.places import normalize_place_name

    City = apps.get_model('local_listings', 'City')
    batch = []
    for city in City.objects.all().only('pk', 'name'):
        city.search_name = normalize_place_name(city.name)
        city.is_major = True
        batch.append(city)
    City.objects.bulk_update(batch, ['search_name', 'is_major'], batch_size=500)


